'use strict';

var concat = require( './../lib' );

var str = concat( 'Hello ', 'World!' );
console.log( str );
// => 'Hello World!'

str = concat( 'Beep ', 'Boop' );
console.log( str );
// => 'Beep Boop'

str = concat( '', 'World!' );
console.log( str );
// => 'World!'

str = concat( 'Hello ', '' );
console.log( str );
// => 'Hello '

str = concat( '', '' );
console.log( str );
// => ''
